+<div class="form-group">
+    <label>City</label>
+    <input @bind="Shipping.City" disabled="@_isValidating" />
+</div>
+
+<div class="form-group">
+    <label>Zip Code</label>
+    <input @bind="Shipping.ZipCode" disabled="@_isValidating" />
+</div>
+
+@if (!string.IsNullOrEmpty(_errorMessage))
+{
+    <div class="validation-error">@_errorMessage</div>
+}
+
+<button disabled="@_isValidating" @onclick="HandleNext">
+    @if (_isValidating)
+    {
+        <span class="spinner" aria-hidden="true"></span>
+        <span>Validating…</span>
+    }
+    else
+    {
+        <span>Next</span>
+    }
+</button>
+
+@code {
+    [Parameter, EditorRequired] public ShippingInfo Shipping { get; set; } = default!;
+    [Parameter] public EventCallback OnNext { get; set; }
+
+    private CancellationTokenSource? _cts;
+    private bool _isValidating;
+    private string? _errorMessage;
+
+    private async Task HandleNext()
+    {
+        _errorMessage = null;
+
+        // Cancel any in-flight validation (e.g. user went back, changed fields, clicked Next again).
+        CancelPendingValidation();
+
+        _cts = new CancellationTokenSource();
+        var token = _cts.Token;
+
+        _isValidating = true;
+        try
+        {
+            var isValid = await AddressValidator.ValidateAddressAsync(
+                Shipping.Address, Shipping.City, Shipping.ZipCode, token);
+
+            token.ThrowIfCancellationRequested();
+
+            if (isValid)
+            {
+                await OnNext.InvokeAsync();
+            }
+            else
+            {
+                _errorMessage = "The address could not be verified. Please check your details.";
+            }
+        }
+        catch (OperationCanceledException)
+        {
+            // Validation was cancelled — nothing to do.
+        }
+        finally
+        {
+            _isValidating = false;
+        }
+    }
+
+    private void CancelPendingValidation()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+        _cts = null;
+    }
+
+    public void Dispose()
+    {
+        CancelPendingValidation();
+    }
+}
